import{_ as r,C as n,o as s,c as e,j as i,E as d,a as l,a2 as o}from"./chunks/framework.C21TwvGF.js";const A=JSON.parse('{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"n":2,"bob":"I-bob · Android muhiti va dasturlash asoslari","lessons":[{"g":4,"title":"Android ekotizimi va Google xizmatlari (1-qism)","lead":"Android ekotizimi va Google xizmatlari (1-qism): GMS va AOSP farqi, Google Play Services roli va arxitekturasi","link":"/mentor/9-sinf-android/hafta-02/dars-1","slide":"/slaydlar/9-sinf-android/hafta-02/dars-1.html","test":"/slaydlar/9-sinf-android/hafta-02/dars-1-test.html"},{"g":5,"title":"Android ekotizimi va Google xizmatlari (2-qism)","lead":"Android ekotizimi va Google xizmatlari (2-qism): Google Play Console, SHA-1 barmoq izi, xavfsizlik va AAB formati","link":"/mentor/9-sinf-android/hafta-02/dars-2","slide":"/slaydlar/9-sinf-android/hafta-02/dars-2.html","test":"/slaydlar/9-sinf-android/hafta-02/dars-2-test.html"},{"g":6,"title":"Android Studio va Android SDK bilan tanishuv (1-qism)","lead":"Android Studio va Android SDK bilan tanishuv (1-qism): Android Studio interfeysi, SDK Manager va SDK Build-Tools","link":"/mentor/9-sinf-android/hafta-02/dars-3","slide":"/slaydlar/9-sinf-android/hafta-02/dars-3.html","test":"/slaydlar/9-sinf-android/hafta-02/dars-3-test.html"}],"test":"/slaydlar/9-sinf-android/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-02/index.md","filePath":"mentor/9-sinf-android/hafta-02/index.md"}'),h={name:"mentor/9-sinf-android/hafta-02/index.md"},m={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},v={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function b(c,a,f,q,k,z){const t=n("Icon");return s(),e("div",null,[i("div",m,[i("h2",u,[d(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha mustaqil amaliy uyga vazifalar ro&#39;yxati:</p><hr><h2 id="_4-dars-android-ekotizimi-va-google-xizmatlari-1-qism" tabindex="-1">4-dars. Android ekotizimi va Google xizmatlari (1-qism) <a class="header-anchor" href="#_4-dars-android-ekotizimi-va-google-xizmatlari-1-qism" aria-label="Permalink to &quot;4-dars. Android ekotizimi va Google xizmatlari (1-qism)&quot;">​</a></h2><ol><li>AOSP va GMS tushunchalari o&#39;rtasidagi asosiy farqlarni ko&#39;rsatuvchi taqqoslash jadvali tuzing (litsenziya, narxi, tarkibi).</li><li>Nima sababdan telefon batareyasini tejash uchun ilovalar to&#39;g&#39;ridan-to&#39;g&#39;ri GPS&#39;ga emas, balki Google Play Services tarkibidagi Fused Location Provider&#39;ga murojaat qiladi?</li><li>Huawei smartfonlarida GMS o&#39;rniga qanday muqobil tizim ishlatilishini va dasturchi bu muammoni kod orqali qanday hal qilishini yozma bayon qiling.</li></ol><hr><h2 id="_5-dars-android-ekotizimi-va-google-xizmatlari-2-qism" tabindex="-1">5-dars. Android ekotizimi va Google xizmatlari (2-qism) <a class="header-anchor" href="#_5-dars-android-ekotizimi-va-google-xizmatlari-2-qism" aria-label="Permalink to &quot;5-dars. Android ekotizimi va Google xizmatlari (2-qism)&quot;">​</a></h2><ol><li>Shaxsiy tasavvuringizdagi mobil ilova uchun to&#39;g&#39;ri va unikal <code>applicationId</code> yozing (masalan, <code>uz.edu.myquiz</code>). Nega ushbu nomni keyinchalik o&#39;zgartirib bo&#39;lmasligini tushuntiring.</li><li>Terminalda SHA-1 barmoq izini olish buyrug&#39;ini yozing va ushbu kalit nima maqsadda ishlatilishini tushuntiring.</li><li>Maxfiy API kalitlarini (masalan, Google Maps API key) nima uchun ochiq kodda qoldirish xavfli va ularni <code>local.properties</code>da saqlashning afzalligi nimada?</li><li>APK va AAB formatlari o&#39;rtasidagi farqni tushuntiring: Dynamic Delivery qanday qilib ilova hajmini 30–50% ga qisqartiradi?</li></ol><hr><h2 id="_6-dars-android-studio-va-android-sdk-bilan-tanishuv" tabindex="-1">6-dars. Android Studio va Android SDK bilan tanishuv <a class="header-anchor" href="#_6-dars-android-studio-va-android-sdk-bilan-tanishuv" aria-label="Permalink to &quot;6-dars. Android Studio va Android SDK bilan tanishuv&quot;">​</a></h2><ol><li>Android Studio interfeysidagi 4 ta asosiy ishchi oynani (Project Explorer, Editor, Logcat, Gradle) va ularning vazifalarini daftaringizga yozing.</li><li>Android SDK arxitekturasining 3 ta asosiy ustunini (SDK Platforms, Platform-Tools, Build-Tools) chizib, har biriga bittadan misol keltiring.</li><li>ADB vositasining 3 ta eng muhim buyrug&#39;ini (<code>adb devices</code>, <code>adb install</code>, <code>adb logcat</code>) yozing va nima ish qilishini bayon qiling.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-100-ballik-tizim" tabindex="-1">Baholash mezonlari (100 ballik tizim) <a class="header-anchor" href="#baholash-mezonlari-100-ballik-tizim" aria-label="Permalink to &quot;Baholash mezonlari (100 ballik tizim)&quot;">​</a></h3><ol><li><p><strong>AOSP va GMS ekotizimi tahlili (30 ball):</strong></p><ul><li>AOSP va GMS farqini to&#39;g&#39;ri tushuntirishi (10 ball);</li><li>Google Play Services, Fused Location va FCM vazifalarini bilishi (10 ball);</li><li>GMS bo&#39;lmagan qurilmalar uchun muqobil yechimlarni asoslashi (10 ball).</li></ul></li><li><p><strong>Identifikatsiya, xavfsizlik va paketlash (35 ball):</strong></p><ul><li><code>applicationId</code> va SHA-1 barmoq izi vazifasini tushunishi (10 ball);</li><li><code>google-services.json</code> fayli va <code>local.properties</code> xavfsizlik qoidalarini bilishi (15 ball);</li><li>APK va AAB farqi hamda Dynamic Delivery mexanizmini to&#39;g&#39;ri ifodalashi (10 ball).</li></ul></li><li><p><strong>Android Studio va SDK bilimlari (35 ball):</strong></p><ul><li>Android Studio oynalari vazifalarini ajrata olishi (10 ball);</li><li>SDK Platforms, Platform-Tools va Build-Tools farqini tushunishi (15 ball);</li><li><code>aapt2</code>, <code>d8</code> va ADB buyruqlarining amaliy ahamiyatini bilishi (10 ball).</li></ul></li></ol><h3 id="kutiladigan-namunaviy-natijalar" tabindex="-1">Kutiladigan namunaviy natijalar <a class="header-anchor" href="#kutiladigan-namunaviy-natijalar" aria-label="Permalink to &quot;Kutiladigan namunaviy natijalar&quot;">​</a></h3><ul><li>O&#39;quvchi API kalitlarni ochiq kodda qoldirish xavfli ekanini va nima sababdan <code>local.properties</code>dan foydalanish kerakligini aniq asoslab berishi kerak;</li><li>AAB formati barcha protsessorlar kodini bitta faylga to&#39;plamasdan, har bir telefonga faqat kerakli qismini berishini to&#39;g&#39;ri ifodalashi lozim.</li></ul>',16))]),i("div",v,[i("h2",g,[d(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>Android ekotizimi va Google xizmatlari (1-qism): GMS va AOSP farqi, Google Play Services roli va arxitekturasi</li><li>Android ekotizimi va Google xizmatlari (2-qism): Google Play Console, SHA-1 barmoq izi, xavfsizlik va AAB formati</li><li>Android Studio va Android SDK bilan tanishuv (1-qism): Android Studio interfeysi, SDK Manager va SDK Build-Tools</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>AOSP va GMS ekotizimi</strong></td><td>AOSP va GMS farqi, Google Play Services, Fused Location va FCM</td><td>30 ball</td></tr><tr><td><strong>Xavfsizlik va paketlash</strong></td><td>applicationId, SHA-1 barmoq izi, google-services.json, APK vs AAB</td><td>35 ball</td></tr><tr><td><strong>Android Studio va SDK</strong></td><td>Android Studio oynalari, SDK Platforms, ADB buyruqlari, aapt2 va d8</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Ekotizim (30)</th><th>Xavfsizlik (35)</th><th>Studio/SDK (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar <code>google-services.json</code> faylini loyihaning ildiz (root) katalogiga noto&#39;g&#39;ri joylashtirishlari yoki SHA-1 kalitini olishda terminal buyrug&#39;ini chalkashtirishlari mumkin. Bunga alohida e&#39;tibor qarating.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> Kompyuterga Android SDK vositalarini to&#39;liq o&#39;rnatib, <code>PATH</code> o&#39;zgaruvchisiga qo&#39;shish va tizim terminalidan to&#39;g&#39;ridan-to&#39;g&#39;ri <code>adb</code> buyruqlarini sinab ko&#39;rish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const S=r(h,[["render",b]]);export{A as __pageData,S as default};
